//! 🟢 🦅 ZeroClaw Axum Host — HTTP/gRPC-Web schema server.
//!
//! Reads the zeroclaw PluginSchema from `/dev/shm/live-schema.json`
//! and serves it over native gRPC (Unix socket) and gRPC-Web/HTTP (TCP).
//! This is the HTTP-facing side of The Shuttle for the zeroclaw plugin.

use op_grpc_bridge::server::{run_zeroclaw_server, ServerConfig};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive("op_grpc_bridge=info".parse()?)
                .add_directive("info".parse()?),
        )
        .init();

    let config = ServerConfig::from_env();
    tracing::info!(?config, "ZeroClaw Axum host starting");
    run_zeroclaw_server(config).await
}

//! D-Bus object for the zeroclaw Axum host.
//!
//! Exposes `/org/opdbus/v1/services/zeroclaw_axum_host` with the runtime
//! configuration properties required by the spec. Writes to `BindAddr` or
//! `SchemaPath` trigger a reload signal; the server task picks it up and
//! reconfigures without restarting the process.

use std::sync::Arc;

use tokio::sync::{mpsc, RwLock};
use tracing::{info, warn};

use crate::schema_loader::SchemaLoader;

const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";

/// D-Bus-facing configuration object for the zeroclaw Axum host.
#[derive(Clone)]
pub struct ZeroclawAxumHostObject {
    bind_addr: Arc<RwLock<String>>,
    schema_path: Arc<RwLock<String>>,
    reload_interval_secs: Arc<RwLock<u32>>,
    loader: Arc<SchemaLoader>,
    rebind_tx: mpsc::Sender<String>,
}

impl ZeroclawAxumHostObject {
    pub fn new(loader: Arc<SchemaLoader>, rebind_tx: mpsc::Sender<String>) -> anyhow::Result<Self> {
        let initial_path = loader.path().to_string_lossy().to_string();
        Ok(Self {
            bind_addr: Arc::new(RwLock::new(DEFAULT_BIND_ADDR.to_string())),
            schema_path: Arc::new(RwLock::new(initial_path)),
            reload_interval_secs: Arc::new(RwLock::new(0)),
            loader,
            rebind_tx,
        })
    }

    /// Read the current TCP bind address.
    async fn bind_addr_value(&self) -> String {
        self.bind_addr.read().await.clone()
    }

    /// Read the current plugin-owned schema file path.
    async fn schema_path_value(&self) -> String {
        self.schema_path.read().await.clone()
    }

    /// Read the current periodic reload interval in seconds.
    async fn reload_interval_value(&self) -> u32 {
        *self.reload_interval_secs.read().await
    }
}

#[zbus::interface(name = "org.opdbus.v1.ZeroclawAxumHost")]
impl ZeroclawAxumHostObject {
    #[zbus(property)]
    async fn bind_addr(&self) -> String {
        self.bind_addr_value().await
    }

    #[zbus(property)]
    async fn set_bind_addr(&self, value: String) {
        let mut addr = self.bind_addr.write().await;
        *addr = value.clone();
        drop(addr);
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_bind = %value, "BindAddr changed; signaling rebind");
        if let Err(e) = self.rebind_tx.send(value).await {
            warn!(error = %e, "failed to send rebind request");
        }
    }

    #[zbus(property)]
    async fn schema_path(&self) -> String {
        self.schema_path_value().await
    }

    #[zbus(property)]
    async fn set_schema_path(&self, value: String) {
        let mut path = self.schema_path.write().await;
        *path = value.clone();
        drop(path);
        self.loader.set_path(value.clone());
        info!(subid = "mut.service.zeroclaw-axum-host.reload@v1", new_path = %value, "SchemaPath changed; reloading");
        if let Err(e) = self.loader.reload().await {
            warn!(error = %e, "schema path reload failed");
            self.loader.set_health_status(e.to_string()).await;
        }
    }

    #[zbus(property)]
    async fn reload_interval_secs(&self) -> u32 {
        self.reload_interval_value().await
    }

    #[zbus(property)]
    async fn set_reload_interval_secs(&self, value: u32) {
        let mut interval = self.reload_interval_secs.write().await;
        *interval = value;
    }

    #[zbus(property)]
    async fn health_status(&self) -> String {
        self.loader.health_status().await
    }
}

/// Register the zeroclaw Axum host object on the system bus.
pub async fn register_zeroclaw_host_object(
    object: ZeroclawAxumHostObject,
) -> anyhow::Result<zbus::Connection> {
    let connection = zbus::Connection::system().await?;
    connection
        .object_server()
        .at("/org/opdbus/v1/services/zeroclaw_axum_host", object)
        .await?;
    info!("registered /org/opdbus/v1/services/zeroclaw_axum_host");
    Ok(connection)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn should_expose_dbus_properties() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("live-schema.json");
        std::fs::write(&path, r#"{"zeroclaw":[{"name":"zeroclaw"}]}"#).unwrap();

        let loader = Arc::new(SchemaLoader::new(&path).unwrap());
        let (rebind_tx, _rebind_rx) = mpsc::channel(1);
        let obj = ZeroclawAxumHostObject::new(loader, rebind_tx).unwrap();

        assert_eq!(obj.bind_addr_value().await, "0.0.0.0:8090");
        assert_eq!(obj.schema_path_value().await, path.to_string_lossy());
        assert_eq!(obj.reload_interval_value().await, 0);
        assert_eq!(obj.health_status().await, "ok");
    }
}

//! D-Bus ↔ gRPC Bidirectional Bridge
//!
//! Provides live synchronization between D-Bus objects and gRPC services:
//! - D-Bus property changes → gRPC streaming updates
//! - gRPC mutations → D-Bus method calls / property sets
//! - D-Bus signals → gRPC server-streaming
//! - All changes flow through the event chain for audit/compliance
//!
//! Architecture:
//! ```text
//!                     ┌─────────────────┐
//!                     │   Event Chain   │ ← Source of truth
//!                     │  (audit + hash) │
//!                     └────────┬────────┘
//!                              │
//!               ┌──────────────┴──────────────┐
//!               ▼                              ▼
//!     ┌─────────────────┐            ┌─────────────────┐
//!     │     D-Bus       │◄──────────►│      gRPC       │
//!     │  (local IPC)    │            │  (remote RPC)   │
//!     └─────────────────┘            └─────────────────┘
//! ```

pub mod chat_service;
pub mod dbus_object;
pub mod grpc_client;
pub mod grpc_server;
pub mod interceptor;
pub mod mutation_engine;
pub mod proto_gen;
pub mod schema_loader;
pub mod server;
pub mod shared_socket;
pub mod tracing;

// Re-export main types
pub use grpc_client::{GrpcClientPool, RemoteEndpoint, RemoteOperationClient};
pub use grpc_server::{run_grpc_server, OperationGrpcServer, PluginSchemaProvider};
pub use interceptor::ghostbridge_interceptor;
pub use mutation_engine::{ChangeSource, ChangeType, MutationEngine, StateChange};
pub use proto_gen::{ProtoGenConfig, ProtoGenerator};
pub use server::{run_zeroclaw_server, ServerConfig};

/// Generated protobuf types — one sub-module per domain proto.
/// All are compiled into the combined operation_descriptor.bin for reflection.
pub mod proto {
    // Core: StateSync, PluginService, EventChainService, OvsdbMirror, RuntimeMirror
    tonic::include_proto!("operation.v1");

    pub mod mail {
        tonic::include_proto!("operation.mail.v1");
    }
    pub mod privacy {
        tonic::include_proto!("operation.privacy.v1");
    }
    pub mod registration {
        tonic::include_proto!("operation.registration.v1");
    }
    pub mod registry {
        tonic::include_proto!("operation.registry.v1");
    }

    /// Zeroclaw plugin schema gRPC service (GetSchema / WatchSchema).
    pub mod zeroclaw {
        tonic::include_proto!("zeroclaw");
    }

    /// ChatService — operator-to-system chat interface (delegator, forced tool calling).
    pub mod chat {
        tonic::include_proto!("op_chat.chat");
    }

    /// Combined FileDescriptorSet covering all domain protos (including chat).
    /// Served by tonic-reflection so clients can discover every service.
    pub const FILE_DESCRIPTOR_SET: &[u8] =
        tonic::include_file_descriptor_set!("operation_descriptor");
}

//! Axum HTTP/gRPC-Web host for the zeroclaw plugin schema.
//!
//! Serves the plugin-owned schema JSON on:
//!   - native gRPC over Unix socket `/run/opdbus/zeroclaw-grpc.sock`
//!   - HTTP/1.1 + gRPC-Web on TCP `0.0.0.0:8090` (configurable via D-Bus)
//!
//! The schema itself is never generated here; it is read from the canonical
//! SchemaEngine monolith at `/dev/shm/live-schema.json`.

use std::net::SocketAddr;
use std::path::PathBuf;
use std::pin::Pin;
use std::sync::Arc;

use async_stream::stream;
use axum::Router;
use tokio::sync::mpsc;
use tonic::{Request as TonicRequest, Response as TonicResponse, Status};
use tower_http::cors::{Any, CorsLayer};
use tracing::info;

use crate::dbus_object::{register_zeroclaw_host_object, ZeroclawAxumHostObject};
use crate::grpc_server::OperationGrpcServer;
use crate::mutation_engine::MutationEngine;
use crate::schema_loader::{SchemaLoader, SchemaReloadEvent};
use crate::tracing::{GhostbridgeTraceLayer, TraceContext};

use crate::grpc_server::build_operation_routes;
use crate::proto::zeroclaw::{
    zeroclaw_service_server::{ZeroclawService, ZeroclawServiceServer},
    GetSchemaRequest, SchemaEvent, SchemaResponse, WatchSchemaRequest,
};

const DEFAULT_UNIX_SOCKET: &str = "/run/opdbus/zeroclaw-grpc.sock";
const DEFAULT_BIND_ADDR: &str = "0.0.0.0:8090";
const DEFAULT_SCHEMA_PATH: &str = "/dev/shm/live-schema.json";

/// Runtime configuration for the zeroclaw Axum host.
#[derive(Clone, Debug)]
pub struct ServerConfig {
    pub plugin_id: String,
    pub schema_path: PathBuf,
    pub unix_socket: PathBuf,
    pub bind_addr: String,
}

impl Default for ServerConfig {
    fn default() -> Self {
        Self {
            plugin_id: "zeroclaw".to_string(),
            schema_path: PathBuf::from(DEFAULT_SCHEMA_PATH),
            unix_socket: PathBuf::from(DEFAULT_UNIX_SOCKET),
            bind_addr: DEFAULT_BIND_ADDR.to_string(),
        }
    }
}

impl ServerConfig {
    /// Load configuration from environment variables, falling back to defaults.
    pub fn from_env() -> Self {
        Self {
            plugin_id: std::env::var("OP_DBUS_SCHEMA_PLUGIN_ID")
                .or_else(|_| std::env::var("ZEROCLAW_PLUGIN_ID"))
                .unwrap_or_else(|_| "zeroclaw".to_string()),
            schema_path: PathBuf::from(
                std::env::var("ZEROCLAW_SCHEMA_PATH")
                    .unwrap_or_else(|_| DEFAULT_SCHEMA_PATH.to_string()),
            ),
            unix_socket: PathBuf::from(
                std::env::var("ZEROCLAW_UNIX_SOCKET")
                    .unwrap_or_else(|_| DEFAULT_UNIX_SOCKET.to_string()),
            ),
            bind_addr: std::env::var("ZEROCLAW_BIND_ADDR")
                .unwrap_or_else(|_| DEFAULT_BIND_ADDR.to_string()),
        }
    }
}

/// Shared state for the gRPC service handlers.
#[derive(Clone)]
struct ZeroclawGrpcService {
    loader: Arc<SchemaLoader>,
}

#[tonic::async_trait]
impl ZeroclawService for ZeroclawGrpcService {
    type WatchSchemaStream =
        Pin<Box<dyn tokio_stream::Stream<Item = Result<SchemaEvent, Status>> + Send>>;

    async fn get_schema(
        &self,
        request: TonicRequest<GetSchemaRequest>,
    ) -> Result<TonicResponse<SchemaResponse>, Status> {
        let context = request
            .extensions()
            .get::<TraceContext>()
            .cloned()
            .unwrap_or_else(|| TraceContext::from_tonic_metadata(request.metadata()));

        let schema_json = self.loader.get().await.to_string();
        let mut response = TonicResponse::new(SchemaResponse {
            schema_json,
            trace_id: context.trace_id.clone(),
            footprint: context.footprint.clone(),
        });
        inject_trace_metadata(&mut response, &context);
        Ok(response)
    }

    async fn watch_schema(
        &self,
        _request: TonicRequest<WatchSchemaRequest>,
    ) -> Result<TonicResponse<Self::WatchSchemaStream>, Status> {
        let mut reload_rx = self.loader.reload_tx().subscribe();
        let loader = self.loader.clone();

        let initial = loader.get().await;
        let stream = stream! {
            yield Ok(SchemaEvent {
                schema_json: initial.to_string(),
                event_type: "initial".to_string(),
            });

            while let Ok(SchemaReloadEvent { event_type }) = reload_rx.recv().await {
                let schema_json = loader.get().await.to_string();
                yield Ok(SchemaEvent {
                    schema_json,
                    event_type,
                });
            }
        };

        Ok(TonicResponse::new(Box::pin(stream)))
    }
}

fn inject_trace_metadata<T>(response: &mut TonicResponse<T>, context: &TraceContext) {
    if let (Ok(trace_id), Ok(footprint)) = (context.trace_id.parse(), context.footprint.parse()) {
        response
            .metadata_mut()
            .insert("x-ghostbridge-trace-id", trace_id);
        response
            .metadata_mut()
            .insert("x-ghostbridge-footprint", footprint);
    }
}

/// Assemble the gRPC service set for the zeroclaw bridge.
///
/// The full backplane surface (StateSync, PluginService, DbusPassthrough,
/// OvsdbMirror, RuntimeMirror, EventChainService, ComponentRegistry, Mail,
/// Privacy, Registration, McpService, ChatService, reflection) comes from the
/// shared [`build_operation_routes`] — identical to what `run_grpc_server` mounts
/// on op-dbus :50051, so reflection never advertises an unmounted service. On top
/// of that the zeroclaw bridge adds its endpoint-specific `ZeroclawService`
/// (plugin-owned schema get/watch).
///
/// Every container shares this one surface over `container.sock`; the assistant
/// container is provisioned exactly like the others (its socket created via the
/// unix-socket plugin's createsocket through PluginService, not a raw Incus proxy
/// device).
fn build_routes(loader: Arc<SchemaLoader>, server: OperationGrpcServer) -> tonic::service::Routes {
    let zeroclaw_svc =
        tonic_web::enable(ZeroclawServiceServer::new(ZeroclawGrpcService { loader }));
    build_operation_routes(server).add_service(zeroclaw_svc)
}

/// Build the axum `Router` that serves the gRPC service over HTTP/gRPC-Web.
pub fn build_axum_app(loader: Arc<SchemaLoader>, server: OperationGrpcServer) -> Router {
    let cors = CorsLayer::new()
        .allow_origin(Any)
        .allow_methods(Any)
        .allow_headers(Any);

    build_routes(loader, server)
        .into_axum_router()
        .layer(cors)
        .layer(GhostbridgeTraceLayer::new())
}

/// Build the tonic `Routes` used for the native-gRPC Unix socket side.
fn build_tonic_routes(
    loader: Arc<SchemaLoader>,
    server: OperationGrpcServer,
) -> tonic::service::Routes {
    build_routes(loader, server)
}

/// Run the zeroclaw Axum host.
///
/// Returns only when both listeners exit (which should not happen under normal
/// operation).
pub async fn run_zeroclaw_server(config: ServerConfig) -> anyhow::Result<()> {
    let loader = Arc::new(SchemaLoader::new_for_plugin(
        &config.schema_path,
        config.plugin_id.clone(),
    )?);

    // Channel for D-Bus-triggered rebind requests. Only `SchemaPath` changes are
    // applied live; `BindAddr` changes are recorded and honored on the next
    // restart.
    let (rebind_tx, mut rebind_rx) = mpsc::channel::<String>(4);

    // D-Bus object for runtime configuration.
    let dbus_object = ZeroclawAxumHostObject::new(loader.clone(), rebind_tx)?;
    let _dbus_connection = register_zeroclaw_host_object(dbus_object).await?;

    // SIGHUP reload watcher.
    let _sighup_handle = loader.clone().watch_sighup();

    // PluginService (PluginService.CallMethod) backed by the authoritative
    // MutationEngine. This is how createunixsocket is invoked: a CallMethod with
    // plugin_id="unix_socket" routes through MutationEngine.mutate →
    // UnixSocketPlugin::create_unix_socket. The sled identity is resolved as
    // the actor_id inside mutate when the caller omits it.
    let event_chain = Arc::new(tokio::sync::RwLock::new(op_state_store::EventChain::new(
        op_state_store::ChainConfig::default(),
    )));
    let ovsdb = Arc::new(op_network::rovs_proxy::OvsdbDbusClient::new());
    let nonnet = Arc::new(op_jsonrpc::nonnet::NonNetDb::new());
    let mutation_engine = Arc::new(MutationEngine::new(event_chain, ovsdb, nonnet));
    mutation_engine.seed_missing_plugin_projections().await?;
    let operation_server = OperationGrpcServer::new(mutation_engine);
    // Attach the semantic shuttle for parity with run_grpc_server so
    // SearchSemanticTrace behaves identically on both endpoints (best-effort:
    // if Qdrant is unavailable the method returns failed_precondition).
    let operation_server = match op_cognitive_mcp::QdrantSemanticShuttle::new().await {
        Ok(shuttle) => operation_server.with_semantic_shuttle(Arc::new(shuttle)),
        Err(error) => {
            tracing::warn!(%error, "semantic shuttle unavailable; SearchSemanticTrace will return failed_precondition");
            operation_server
        }
    };

    // Unix socket listener for native gRPC.
    let unix_socket = config.unix_socket.clone();
    if let Some(parent) = unix_socket.parent() {
        let _ = std::fs::create_dir_all(parent);
    }
    let _ = std::fs::remove_file(&unix_socket);
    let unix_listener = tokio::net::UnixListener::bind(&unix_socket)?;
    info!(path = %unix_socket.display(), "zeroclaw native gRPC listening on Unix socket");

    let unix_incoming = tokio_stream::wrappers::UnixListenerStream::new(unix_listener);

    // accept_http1(true): tonic-web serves gRPC-Web over HTTP/1.1, which is what
    // browsers (and xray's tls-h1 fallback forwarding to this socket) speak. Without
    // it the socket is h2-only and rejects browser gRPC-Web. Matches the TCP/axum side.
    let tonic_server = tonic::transport::Server::builder()
        .accept_http1(true)
        .add_routes(build_tonic_routes(loader.clone(), operation_server.clone()))
        .serve_with_incoming(unix_incoming);

    // TCP listener for HTTP + gRPC-Web.
    let bind_addr: SocketAddr = config.bind_addr.parse()?;
    let tcp_listener = tokio::net::TcpListener::bind(bind_addr).await?;
    info!(addr = %bind_addr, "zeroclaw HTTP/gRPC-Web listening on TCP");

    let axum_app = build_axum_app(loader.clone(), operation_server);
    let tcp_server = axum::serve(tcp_listener, axum_app);

    // Rebind task: when a new bind address is requested, restart the TCP server.
    // The current implementation starts the initial TCP server; subsequent
    // rebinds require a restart to keep the listener lifecycle simple and safe.
    let rebind_task = tokio::spawn(async move {
        while let Some(new_bind) = rebind_rx.recv().await {
            info!(new_bind = %new_bind, "D-Bus rebind request received; will be honored on next restart");
        }
    });

    let (unix_result, tcp_result) = tokio::join!(tonic_server, tcp_server);
    let _ = rebind_task.await;
    unix_result.map_err(|e| anyhow::anyhow!("Unix server error: {}", e))?;
    tcp_result.map_err(|e| anyhow::anyhow!("TCP server error: {}", e))
}

//! Proto Generator - Generate protobuf definitions from PluginSchema
//!
//! Converts operation-dbus plugin schemas to protobuf message and service
//! definitions, enabling dynamic schema-driven gRPC.
//!
//! For plugins using `#[derive(schemars::JsonSchema)]` on method input types,
//! this generates equivalent protobuf services that mirror the D-Bus objects
//! registered by SchemaBackedInterface.

use op_state_store::{FieldType, PluginSchema, SchemaCatalog, SchemaRegistry};
use std::fmt::Write;

/// Configuration for protobuf generation
#[derive(Debug, Clone)]
pub struct ProtoGenConfig {
    /// Package name for generated proto
    pub package_name: String,
    /// Whether to generate service definitions
    pub generate_services: bool,
    /// Whether to include validation annotations
    pub include_validation: bool,
    /// Whether to generate streaming RPCs for state changes
    pub generate_streams: bool,
}

impl Default for ProtoGenConfig {
    fn default() -> Self {
        Self {
            package_name: "operation.v1".to_string(),
            generate_services: true,
            include_validation: true,
            generate_streams: true,
        }
    }
}

/// Generate protobuf definitions from plugin schemas and their method declarations.
///
/// Each plugin's `MethodDecl` entries become typed RPCs. This mirrors the D-Bus
/// objects created by `SchemaBackedInterface.register_objects()`.
pub fn generate_plugin_method_protos(plugin_schemas: &[(String, PluginSchema)]) -> String {
    let mut output = String::new();

    writeln!(output, "syntax = \"proto3\";").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "package operation.plugin.v1;").unwrap();
    writeln!(output).unwrap();
    writeln!(output, "import \"google/protobuf/struct.proto\";").unwrap();
    writeln!(output).unwrap();

    let mut plugin_ids: Vec<&String> = plugin_schemas.iter().map(|(id, _)| id).collect();
    plugin_ids.sort();

    for plugin_id in plugin_ids {
        let (_, schema) = plugin_schemas.iter().find(|(id, _)| id == plugin_id).unwrap();
        generate_plugin_service(&mut output, plugin_id, schema);
    }

    output
}

/// Generate a service for a single plugin with typed method messages.
fn generate_plugin_service(output: &mut String, plugin_id: &str, schema: &PluginSchema) {
    writeln!(output, "// ================================================").unwrap();
    writeln!(output, "// Plugin: {}", plugin_id).unwrap();
    writeln!(output, "// {} service typed methods", schema.description).unwrap();
    writeln!(output, "// ================================================").unwrap();
    writeln!(output).unwrap();

    let service_name = to_pascal_case(plugin_id);
    writeln!(output, "service {} {{", service_name).unwrap();

    let mut method_names: Vec<&String> = schema.methods.keys().collect();
    method_names.sort();

    for method_name in method_names {
        let method = &schema.methods[method_name];
        let subid = method.subid.as_str();
        let cap = method.required_capability.as_deref().unwrap_or("none");

        writeln!(output, "  // subid: {}", subid).unwrap();
        writeln!(output, "  // capability: {}", cap).unwrap();

        writeln!(
            output,
            "  rpc {}(google.protobuf.Struct) returns (google.protobuf.Struct);",
            method_name
        )
        .unwrap();
    }

    writeln!(output, "}}").unwrap();
    writeln!(output).unwrap();
}

// ProtoGenerator struct and other methods (kept for compatibility)
pub struct ProtoGenerator {
    config: ProtoGenConfig,
}

impl ProtoGenerator {
    pub fn new(config: ProtoGenConfig) -> Self {
        Self { config }
    }

    pub fn generate_for_schema(&self, schema: &PluginSchema) -> String {
        let mut output = String::new();
        writeln!(output, "syntax = \"proto3\";").unwrap();
        writeln!(output).unwrap();
        writeln!(output, "package {};", self.config.package_name).unwrap();
        writeln!(output).unwrap();
        writeln!(output, "import \"google/protobuf/struct.proto\";").unwrap();
        writeln!(output).unwrap();

        let message_name = to_pascal_case(&schema.name);
        writeln!(output, "message {} {{", message_name).unwrap();

        let mut fields: Vec<(&str, &op_state_store::FieldSchema)> = schema
            .fields
            .iter()
            .map(|(field_name, field_schema)| (field_name.as_str(), field_schema))
            .collect();
        fields.sort_unstable_by(|left, right| left.0.cmp(right.0));

        for (field_num, (field_name, field_schema)) in (1..).zip(fields) {
            let proto_type = self.field_type_to_proto(&field_schema.field_type);
            let optional_marker = if field_schema.required { "" } else { "optional " };
            writeln!(
                output,
                "  {}{} {} = {};",
                optional_marker, proto_type, field_name, field_num
            )
            .unwrap();
        }

        writeln!(output, "}}").unwrap();
        output
    }

    pub fn generate_for_catalog(&self, catalog: &SchemaCatalog) -> String {
        let mut output = String::new();
        let mut schema_names: Vec<&str> = catalog.list();
        schema_names.sort_unstable();

        writeln!(output, "syntax = \"proto3\";").unwrap();
        writeln!(output).unwrap();
        writeln!(output, "package {};", self.config.package_name).unwrap();
        writeln!(output).unwrap();
        writeln!(output, "import \"google/protobuf/struct.proto\";").unwrap();
        writeln!(output).unwrap();

        for schema_name in schema_names {
            let Some(schema) = catalog.get(schema_name) else {
                continue;
            };
            writeln!(output, "// =============================================").unwrap();
            writeln!(output, "// {} - {}", schema.name, schema.description).unwrap();
            writeln!(output, "// =============================================").unwrap();
            writeln!(output).unwrap();

            self.generate_message(&mut output, schema);
            self.generate_crud_messages(&mut output, schema);

            if self.config.generate_services {
                self.generate_service(&mut output, schema);
            }

            writeln!(output).unwrap();
        }

        self.generate_unified_service(&mut output, catalog);
        output
    }

    pub fn generate_for_registry(&self, registry: &SchemaRegistry) -> String {
        self.generate_for_catalog(registry)
    }

    fn generate_message(&self, output: &mut String, schema: &PluginSchema) {
        let message_name = to_pascal_case(&schema.name);
        writeln!(output, "message {} {{", message_name).unwrap();

        let mut fields: Vec<(&str, &op_state_store::FieldSchema)> = schema
            .fields
            .iter()
            .map(|(field_name, field_schema)| (field_name.as_str(), field_schema))
            .collect();
        fields.sort_unstable_by(|left, right| left.0.cmp(right.0));

        for (field_num, (field_name, field_schema)) in (1..).zip(fields) {
            let proto_type = self.field_type_to_proto(&field_schema.field_type);
            let optional_marker = if field_schema.required { "" } else { "optional " };
            writeln!(
                output,
                "  {}{} {} = {};",
                optional_marker, proto_type, field_name, field_num
            )
            .unwrap();
        }

        writeln!(output, "}}").unwrap();
        writeln!(output).unwrap();
    }

    fn generate_crud_messages(&self, output: &mut String, schema: &PluginSchema) {
        let message_name = to_pascal_case(&schema.name);

        writeln!(output, "message Get{}Request {{", message_name).unwrap();
        writeln!(output, "  string object_path = 1;").unwrap();
        writeln!(output, "}}").unwrap();

        writeln!(output, "message Get{}Response {{", message_name).unwrap();
        writeln!(output, "  {} state = 1;", message_name).unwrap();
        writeln!(output, "  string error = 2;").unwrap();
        writeln!(output, "}}").unwrap();

        if self.config.generate_streams {
            writeln!(output, "message {}Update {{", message_name).unwrap();
            writeln!(output, "  string object_path = 1;").unwrap();
            writeln!(output, "  {} state = 2;", message_name).unwrap();
            writeln!(output, "}}").unwrap();
        }

        writeln!(output).unwrap();
    }

    fn generate_service(&self, output: &mut String, schema: &PluginSchema) {
        let service_name = to_pascal_case(&schema.name);

        writeln!(output, "service {}Service {{", service_name).unwrap();
        writeln!(
            output,
            "  rpc Get(Get{}Request) returns (Get{}Response);",
            service_name, service_name
        )
        .unwrap();
        writeln!(output, "}}").unwrap();
        writeln!(output).unwrap();
    }

    fn generate_unified_service(&self, output: &mut String, _catalog: &SchemaCatalog) {
        writeln!(output, "service OperationService {{").unwrap();
        writeln!(
            output,
            "  rpc Get(GenericGetRequest) returns (GenericGetResponse);"
        )
        .unwrap();
        writeln!(output, "}}").unwrap();
    }

    fn field_type_to_proto(&self, field_type: &FieldType) -> String {
        match field_type {
            FieldType::String => "string".to_string(),
            FieldType::Integer => "int64".to_string(),
            FieldType::Float => "double".to_string(),
            FieldType::Boolean => "bool".to_string(),
            FieldType::Array(inner) => format!("repeated {}", self.field_type_to_proto(inner)),
            FieldType::Object(_) => "google.protobuf.Struct".to_string(),
            FieldType::Enum(_) => "string".to_string(),
            FieldType::OneOf(_) => "google.protobuf.Value".to_string(),
            FieldType::Any => "google.protobuf.Value".to_string(),
        }
    }
}

/// Convert string to PascalCase
pub fn to_pascal_case(s: &str) -> String {
    s.split(['_', '-', ' ', '.'])
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().chain(chars).collect(),
            }
        })
        .collect()
}

/// Convert string to snake_case
#[cfg(test)]
fn to_snake_case(s: &str) -> String {
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() && i > 0 {
            result.push('_');
        }
        result.push(c.to_lowercase().next().unwrap_or(c));
    }
    result
}

