        "data",
        "1.0.0",
        "Cognitive memory — namespaces, embeddings, search",
        &state,
    );

    // Add methods to schema
    let methods = vec![
        cap_method("create_namespace", SideEffect::Create, false, "memory.namespace.create", "mut.memory.memory.create-namespace@v1"),
        cap_method("delete_namespace", SideEffect::Delete, true, "memory.namespace.delete", "mut.memory.memory.delete-namespace@v1"),
        cap_method("query_namespace", SideEffect::Read, false, "memory.namespace.read", "mut.memory.memory.query-namespace@v1"),
        cap_method("insert_entry", SideEffect::Create, false, "memory.entry.create", "mut.memory.memory.insert-entry@v1"),
        cap_method("update_entry", SideEffect::Mutate, false, "memory.entry.write", "mut.memory.memory.update-entry@v1"),
        cap_method("get_entry", SideEffect::Read, false, "memory.entry.read", "mut.memory.memory.get-entry@v1"),
        cap_method("delete_entry", SideEffect::Delete, true, "memory.entry.delete", "mut.memory.memory.delete-entry@v1"),
        cap_method("clear_namespace", SideEffect::Mutate, true, "memory.namespace.clear", "mut.memory.memory.clear-namespace@v1"),
        cap_method("get_stats", SideEffect::Read, false, "memory.stats.read", "mut.memory.memory.get-stats@v1"),
        cap_method("compact", SideEffect::Mutate, true, "memory.memory.compact", "mut.memory.memory.compact@v1"),
    ];

    for method in methods {
        builder = builder.method(method);
    }

    builder.build()
}

