pub(crate) fn memory_schema() -> PluginSchema {
    let state =
        simd_json::serde::to_owned_value(super::memory_plugin::MemoryPlugin::current_state())
            .unwrap_or_else(|_| simd_json::json!({}));

    let mut builder = schema_from_state(
        "memory",
        "data",
        "1.0.0",
        "Cognitive memory — namespaces, embeddings, search",
        &state,
    );

    // Add methods to schema with typed returns
    let methods = vec![
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            CreateNamespaceInput,
            CreateNamespaceOutput,
            SideEffect::Create,
            false,
            "memory.namespace.create",
            "mut.memory.memory.create-namespace@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            DeleteNamespaceInput,
            DeleteNamespaceOutput,
            SideEffect::Delete,
            true,
            "memory.namespace.delete",
            "mut.memory.memory.delete-namespace@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            QueryNamespaceInput,
            QueryNamespaceOutput,
            SideEffect::Access,
            false,
            "memory.namespace.read",
            "mut.memory.memory.query-namespace@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            InsertEntryInput,
            InsertEntryOutput,
            SideEffect::Create,
            false,
            "memory.entry.create",
            "mut.memory.memory.insert-entry@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            UpdateEntryInput,
            UpdateEntryOutput,
            SideEffect::Mutate,
            false,
            "memory.entry.write",
            "mut.memory.memory.update-entry@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            GetEntryInput,
            GetEntryOutput,
            SideEffect::Access,
            false,
            "memory.entry.read",
            "mut.memory.memory.get-entry@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            DeleteEntryInput,
            DeleteEntryOutput,
            SideEffect::Delete,
            true,
            "memory.entry.delete",
            "mut.memory.memory.delete-entry@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            ClearNamespaceInput,
            ClearNamespaceOutput,
            SideEffect::Mutate,
            true,
            "memory.namespace.clear",
            "mut.memory.memory.clear-namespace@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            GetStatsInput,
            GetStatsOutput,
            SideEffect::Access,
            false,
            "memory.stats.read",
            "mut.memory.memory.get-stats@v1",
        ),
        super::plugin_schema_defs::method_decl_from_schemars_with_output(
            CompactInput,
            CompactOutput,
            SideEffect::Mutate,
            true,
            "memory.memory.compact",
            "mut.memory.memory.compact@v1",
        ),
    ];

    for method in methods {
        builder = builder.method(method);
    }

    builder.build()
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("memory", |_ctx| std::sync::Arc::new(MemoryPlugin::new()))
}

