use super::plugin_schema_defs::schema_from_state;
use super::plugin_schema_defs::method_decl_from_schemars_with_output;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin, SideEffect};
