    pub deleted: bool,
}
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ClearNamespaceInput {
    /// Namespace identifier to clear
    pub name: String,
}
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ClearNamespaceOutput {
    /// Success status
    pub success: bool,
